import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' });
await page.locator('#btnNewGame').click();
await page.waitForTimeout(100);
const joystick = await page.locator('#joystick').boundingBox();
if (!joystick || await page.locator('#joystick').isHidden()) throw new Error('Joystick not visible after starting game');
await page.mouse.move(joystick.x + joystick.width / 2, joystick.y + joystick.height / 2);
await page.mouse.down();
await page.mouse.move(joystick.x + joystick.width / 2 + 42, joystick.y + joystick.height / 2, { steps: 3 });
const moved = await page.locator('#stickKnob').evaluate(el => getComputedStyle(el).transform);
if (moved === 'none' || moved === 'matrix(1, 0, 0, 1, 0, 0)') throw new Error(`Joystick did not move: ${moved}`);
await page.mouse.up();
await page.waitForTimeout(100);
const reset = await page.locator('#stickKnob').evaluate(el => getComputedStyle(el).transform);
if (reset !== 'matrix(1, 0, 0, 1, 0, 0)') throw new Error(`Joystick did not reset: ${reset}`);
const clock = page.locator('#hudClock');
await page.waitForTimeout(300);
const beforePause = await clock.textContent();
await page.locator('#btnPauseTop').click();
if (await page.locator('#pauseScreen').isHidden()) throw new Error('Pause dialog did not appear');
const pausedClock = await clock.textContent();
await page.waitForTimeout(400);
if ((await clock.textContent()) !== pausedClock) throw new Error('Game clock advanced while paused');
await page.keyboard.press('ArrowRight');
await page.locator('#btnResume').click();
if (!(await page.locator('#pauseScreen').isHidden())) throw new Error('Resume did not dismiss pause dialog');
await page.evaluate(() => {
  Object.defineProperty(document, 'hidden', { configurable: true, value: true });
  document.dispatchEvent(new Event('visibilitychange'));
});
if (await page.locator('#pauseScreen').isHidden()) throw new Error('Visibility change did not pause game');
await page.evaluate(() => {
  Object.defineProperty(document, 'hidden', { configurable: true, value: false });
  document.dispatchEvent(new Event('visibilitychange'));
});
await page.locator('#btnResume').click();
await page.waitForTimeout(400);
if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
const bounds = await page.evaluate(() => ({ w: document.documentElement.scrollWidth, h: document.documentElement.scrollHeight, vw: innerWidth, vh: innerHeight }));
if (bounds.w > bounds.vw || bounds.h > bounds.vh) throw new Error(`Unexpected mobile overflow: ${JSON.stringify(bounds)}`);
mkdirSync('/tmp/opencode/wild-frontier-check', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/wild-frontier-check/latest-mobile.jpg', type: 'jpeg', quality: 76 });
console.log(JSON.stringify({ joystickMoved: moved, joystickReset: reset, clockBeforePause: beforePause, clockPaused: pausedClock, visibilityPause: true, bounds, screenshot: '/tmp/opencode/wild-frontier-check/latest-mobile.jpg', errors }, null, 2));
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(100);
if (await page.locator('#rotateGate').isHidden()) throw new Error('Portrait rotation hint not visible');
await page.locator('#btnRotateSkip').click();
if (!(await page.locator('#rotateGate').isHidden())) throw new Error('Portrait override failed');
console.log('Portrait layout and continue override verified.');
await browser.close();

